function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof BASTAR_INFO&&(e.innerHTML=BASTAR_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderProcess(){const e=document.getElementById("process-steps");e&&"undefined"!=typeof PROCESS_STEPS&&(e.innerHTML=PROCESS_STEPS.map(e=>`\n        <div class="step-card">\n            <div class="step-num">Step ${e.step}</div>\n            <div class="step-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderDesigns(){const e=document.getElementById("designs-grid");e&&"undefined"!=typeof TRADITIONAL_DESIGNS&&(e.innerHTML=TRADITIONAL_DESIGNS.map(e=>`\n        <div class="design-card">\n            <h3>✨ ${e.name}</h3>\n            <p>${e.description}</p>\n        </div>\n    `).join(""))}function renderArtisan(){if("undefined"==typeof ARTISAN_SPOTLIGHT)return;const e=document.getElementById("artisan-title"),n=document.getElementById("artisan-desc");e&&(e.textContent=ARTISAN_SPOTLIGHT.title),n&&(n.textContent=ARTISAN_SPOTLIGHT.description)}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderProcess(),renderDesigns(),renderArtisan(),renderGallery(),renderReferences(),initThemeToggle()});